// Minimal side‑scroll runner for canvas with id="game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width;
  const height = canvas.height;

  const player = {
    x: 50,
    y: height - 30,
    w: 20,
    h: 30,
    vy: 0,
    gravity: 0.6,
    jumpStrength: -12,
    onGround: true,
    draw() {
      ctx.fillStyle = '#0f0';
      ctx.fillRect(this.x, this.y, this.w, this.h);
    },
    update() {
      this.vy += this.gravity;
      this.y += this.vy;
      if (this.y + this.h >= height) {
        this.y = height - this.h;
        this.vy = 0;
        this.onGround = true;
      } else {
        this.onGround = false;
      }
    },
    jump() {
      if (this.onGround) this.vy = this.jumpStrength;
    }
  };

  const obstacles = [];
  let obstacleTimer = 0;
  const obstacleInterval = 90; // frames between obstacles
  const speed = 4;

  function spawnObstacle() {
    const size = 20 + Math.random() * 30; // height 20‑50
    obstacles.push({ x: width, y: height - size, w: 20, h: size });
  }

  function updateObstacles() {
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= speed;
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }
  }

  function drawObstacles() {
    ctx.fillStyle = '#f00';
    obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
  }

  function checkCollision() {
    const p = player;
    for (const o of obstacles) {
      if (
        p.x < o.x + o.w &&
        p.x + p.w > o.x &&
        p.y < o.y + o.h &&
        p.y + p.h > o.y
      ) {
        return true;
      }
    }
    return false;
  }

  let gameOver = false;
  function loop() {
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
      return;
    }
    ctx.clearRect(0, 0, width, height);
    // ground line
    ctx.fillStyle = '#555';
    ctx.fillRect(0, height - 5, width, 5);

    // update & draw
    player.update();
    player.draw();

    if (obstacleTimer <= 0) {
      spawnObstacle();
      obstacleTimer = obstacleInterval;
    } else {
      obstacleTimer--;
    }
    updateObstacles();
    drawObstacles();

    if (checkCollision()) {
      gameOver = true;
    }
    requestAnimationFrame(loop);
  }

  // start on user interaction (required by some browsers)
  const start = () => {
    canvas.removeEventListener('click', start);
    canvas.addEventListener('click', () => player.jump());
    requestAnimationFrame(loop);
  };
  canvas.addEventListener('click', start);
})();
